.theme-toggle:hover .theme-orb, .theme-toggle[aria-expanded="true"] .theme-orb { transform: scale(1.06); box-shadow: 0 0 18px 4px var(--orb-glow), inset 0 0 12px var(--orb-glow); }
.theme-menu { position: absolute; left: 0; bottom: calc(100% + 8px); width: 240px; display: grid; padding: 5px; border: 1px solid var(--green); background: var(--panel-raised); box-shadow: 0 12px 28px rgba(0, 0, 0, .45); }
