  .skill-group:last-child { border-bottom: 0; }
  .skill-group h3 { margin: 12px 0 6px; }
  .about-contact-grid { grid-template-columns: 1fr; gap: 0; }
  .about-contact-grid .content-section { padding-bottom: 54px; }
