.home-screen.is-active { grid-template-columns: minmax(0, 1.15fr) minmax(270px, .85fr); gap: clamp(28px, 5vw, 72px); overflow: hidden; }
.home-content { min-width: 0; }
.home-directory { align-self: center; min-width: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; perspective: 760px; perspective-origin: center bottom; }
.directory-heading { grid-column: 1 / -1; min-height: 34px; display: flex; align-items: center; justify-content: space-between; gap: 12px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
