  renderExperienceFolder(folderId, animate = true) {
    const folder = Model.experienceFolders.find((item) => item.id === folderId);
    if (!folder) return;
    Model.state.activeFolder = folderId;
    this.openFolder = folderId;
    this.els.explorer.classList.add("is-expanded");
    let openButton = null;
    this.els.folderButtons.forEach((button) => {
      const isOpen = button.dataset.folder === folderId;
      button.classList.toggle("is-open", isOpen);
      button.setAttribute("aria-expanded", String(isOpen));
      if (isOpen) openButton = button;
    });
    this.els.folderPath.textContent = `/${folder.label}`;
    this.els.folderStatus.textContent = "ACCESS GRANTED";

    const fragment = document.createDocumentFragment();
    Model[folder.source].forEach((item, index) => {
      const entry = document.createElement(item.url ? "a" : "article");
      entry.className = "folder-entry";
      entry.style.setProperty("--entry-index", index);
      if (item.url) {
        entry.href = item.url;
        entry.target = "_blank";
        entry.rel = "noopener noreferrer";
      }

      const tag = document.createElement("span");
      tag.className = "card-tag";
      tag.textContent = item.tag;
      const title = document.createElement("h4");
      title.textContent = item.title;
      const description = document.createElement("p");
      description.textContent = item.desc;
      const meta = document.createElement("span");
      meta.className = "card-meta";
      meta.textContent = item.meta;
      entry.append(tag, title, description, meta);
      if (item.cta) {
        const cta = document.createElement("span");
        cta.className = "card-cta";
        cta.textContent = `${item.cta} ↗`;
        entry.append(cta);
      }
      fragment.append(entry);
    });

    this.els.folderItems.replaceChildren(fragment);
    this.els.explorer.classList.remove("is-opening");
    this.els.folderItems.classList.remove("is-opening");
    this.els.explorer.querySelector(".folder-morph")?.remove();
    void this.els.explorer.offsetWidth;
    if (animate) {
      this.els.explorer.classList.add("is-opening");
      this.els.folderItems.classList.add("is-opening");
      this.playFolderMorph(openButton);
    } else {
      this.els.folderItems.classList.add("is-opening");
    }
  },

  playFolderMorph(button) {
    if (!button || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const panel = this.els.folderPanel;
    const host = this.els.explorer.getBoundingClientRect();
    const from = button.getBoundingClientRect();
    if (!from.width || !panel.offsetWidth) return;

    const startHeight = from.height * 0.88;
    const morph = document.createElement("div");
    morph.className = "folder-morph";
    morph.setAttribute("aria-hidden", "true");
    const geometry = {
      "--mx0": from.left - host.left + 5,
      "--my0": from.bottom - host.top - 5 - startHeight,
      "--mw0": from.width - 10,
      "--mh0": startHeight,
      "--mx1": panel.offsetLeft,
      "--my1": panel.offsetTop,
      "--mw1": panel.offsetWidth,
      "--mh1": panel.offsetHeight,
    };
    Object.entries(geometry).forEach(([name, value]) => morph.style.setProperty(name, `${value}px`));
    morph.addEventListener("animationend", (event) => {
      if (event.animationName === "folder-morph-box") morph.remove();
    });
    this.els.explorer.append(morph);
    window.setTimeout(() => morph.remove(), 1000);
  },

  collapseExperienceFolder() {
    if (!this.openFolder) return;
    this.openFolder = null;
    this.els.explorer.classList.remove("is-expanded");
    this.els.folderButtons.forEach((button) => {
      button.classList.remove("is-open");
      button.setAttribute("aria-expanded", "false");
    });
  },

  getSavedTheme() {
    try {
      const savedTheme = localStorage.getItem("portfolio-theme");
      return Model.themes.some((theme) => theme.id === savedTheme) ? savedTheme : "hacker";
    } catch {
      return "hacker";
    }
  },

