        cta.textContent = `${item.cta} ↗`;
        entry.append(cta);
      }
      fragment.append(entry);
    });

    this.els.folderItems.replaceChildren(fragment);
    this.els.explorer.classList.remove("is-opening");
    this.els.folderItems.classList.remove("is-opening");
    this.els.explorer.querySelector(".folder-morph")?.remove();
    void this.els.explorer.offsetWidth;
    if (animate) {
      this.els.explorer.classList.add("is-opening");
      this.els.folderItems.classList.add("is-opening");
      this.playFolderMorph(openButton);
    } else {
      this.els.folderItems.classList.add("is-opening");
    }
  },

  playFolderMorph(button) {
    if (!button || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const panel = this.els.folderPanel;
    const host = this.els.explorer.getBoundingClientRect();
    const from = button.getBoundingClientRect();
    if (!from.width || !panel.offsetWidth) return;

    const startHeight = from.height * 0.88;
    const morph = document.createElement("div");
    morph.className = "folder-morph";
    morph.setAttribute("aria-hidden", "true");
    const geometry = {
      "--mx0": from.left - host.left + 5,
      "--my0": from.bottom - host.top - 5 - startHeight,
      "--mw0": from.width - 10,
      "--mh0": startHeight,
      "--mx1": panel.offsetLeft,
      "--my1": panel.offsetTop,
      "--mw1": panel.offsetWidth,
      "--mh1": panel.offsetHeight,
    };
    Object.entries(geometry).forEach(([name, value]) => morph.style.setProperty(name, `${value}px`));
    morph.addEventListener("animationend", (event) => {
      if (event.animationName === "folder-morph-box") morph.remove();
    });
    this.els.explorer.append(morph);
    window.setTimeout(() => morph.remove(), 1000);
  },

  collapseExperienceFolder() {
    this.openFolder = null;
    this.els.explorer.classList.remove("is-expanded", "is-opening");
    this.els.folderItems.classList.remove("is-opening");
    this.els.explorer.querySelector(".folder-morph")?.remove();
    this.els.folderButtons.forEach((button) => {
      button.classList.remove("is-open");
      button.setAttribute("aria-expanded", "false");
    });
    this.els.folderPath.textContent = "/";
    this.els.folderStatus.textContent = "STANDBY";
    this.els.folderItems.replaceChildren();
  },

  getSavedTheme() {
    try {
      const savedTheme = localStorage.getItem("portfolio-theme");
      return Model.themes.some((theme) => theme.id === savedTheme) ? savedTheme : "hacker";
    } catch {
      return "hacker";
    }
  },

  setTheme(themeId, persist = true) {
    const theme = Model.themes.find((item) => item.id === themeId) || Model.themes[0];
    Model.state.theme = theme.id;
    document.body.dataset.theme = theme.id;
    this.els.themeCurrent.textContent = theme.label;
    this.els.themeToggle.setAttribute("aria-label", `Choose visual theme. Current theme: ${theme.label}`);
    this.els.themeChoices.forEach((choice) => {
      const isSelected = choice.dataset.themeChoice === theme.id;
      choice.classList.toggle("is-active", isSelected);
      choice.setAttribute("aria-checked", String(isSelected));
    });
    if (persist) {
      try {
        localStorage.setItem("portfolio-theme", theme.id);
      } catch {}
    }
  },

  setThemeMenuOpen(isOpen, returnFocus = false) {
    this.els.themeMenu.hidden = !isOpen;
    this.els.themeToggle.setAttribute("aria-expanded", String(isOpen));
    if (isOpen) {
      const selectedChoice = this.els.themeChoices.find((choice) => choice.getAttribute("aria-checked") === "true");
      selectedChoice?.focus();
    } else if (returnFocus) {
      this.els.themeToggle.focus();
    }
  },

  renderCards(items, container, className) {
    const fragment = document.createDocumentFragment();
    items.forEach((item) => {
      const card = document.createElement(item.url ? "a" : "article");
      card.className = className;
      if (!item.url) card.tabIndex = -1;
      if (item.url) {
        card.href = item.url;
        card.target = "_blank";
        card.rel = "noopener noreferrer";
      }

      const tag = document.createElement("span");
      tag.className = "card-tag";
      tag.textContent = item.tag;
      const title = document.createElement("h4");
      title.textContent = item.title;
      const description = document.createElement("p");
      description.textContent = item.desc;
      const meta = document.createElement("span");
      meta.className = "card-meta";
      meta.textContent = item.meta;
      card.append(tag, title, description, meta);

      if (item.cta) {
        const linkText = document.createElement("span");
        linkText.className = "card-cta";
        linkText.textContent = `${item.cta} ↗`;
        card.append(linkText);
      }
      fragment.appendChild(card);
    });
    container.replaceChildren(fragment);
  },

  renderContacts(contacts) {
    const fragment = document.createDocumentFragment();
    contacts.forEach((contact) => {
      const link = document.createElement("a");
      link.className = "contact-chip";
      link.href = contact.href;
      link.textContent = contact.label;
      if (contact.external) {
        link.target = "_blank";
        link.rel = "noopener noreferrer";
      }
      if (contact.download) link.download = contact.download;
      fragment.appendChild(link);
    });
    this.els.contacts.replaceChildren(fragment);
  },

  updateClock() {
    this.els.clock.textContent = new Intl.DateTimeFormat("en-GB", {
      timeZone: "Europe/Madrid",
      hour: "2-digit",
      minute: "2-digit",
    }).format(new Date());
  },

  playSelect() {
    this.els.audio.currentTime = 0;
    this.els.audio.play().catch(() => {});
  },
};

