    const fragment = document.createDocumentFragment();
    items.forEach((item) => {
      const card = document.createElement(item.url ? "a" : "article");
      card.className = className;
      if (!item.url) card.tabIndex = -1;
      if (item.url) {
        card.href = item.url;
        card.target = "_blank";
        card.rel = "noopener noreferrer";
      }

      const tag = document.createElement("span");
      tag.className = "card-tag";
      tag.textContent = item.tag;
      const title = document.createElement("h4");
      title.textContent = item.title;
      const description = document.createElement("p");
      description.textContent = item.desc;
      const meta = document.createElement("span");
      meta.className = "card-meta";
      meta.textContent = item.meta;
      card.append(tag, title, description, meta);

      if (item.cta) {
        const linkText = document.createElement("span");
        linkText.className = "card-cta";
        linkText.textContent = `${item.cta} ↗`;
        card.append(linkText);
      }
      fragment.appendChild(card);
    });
    container.replaceChildren(fragment);
  },

  renderContacts(contacts) {
    const fragment = document.createDocumentFragment();
    contacts.forEach((contact) => {
      const link = document.createElement("a");
      link.className = "contact-chip";
      link.href = contact.href;
      link.textContent = contact.label;
      if (contact.external) {
        link.target = "_blank";
        link.rel = "noopener noreferrer";
      }
      if (contact.download) link.download = contact.download;
      fragment.appendChild(link);
    });
    this.els.contacts.replaceChildren(fragment);
  },

  updateClock() {
    this.els.clock.textContent = new Intl.DateTimeFormat("en-GB", {
      timeZone: "Europe/Madrid",
      hour: "2-digit",
      minute: "2-digit",
    }).format(new Date());
  },

  playSelect() {
    this.els.audio.currentTime = 0;
    this.els.audio.play().catch(() => {});
  },
};

