body[data-theme="cyberpunk"] {
  --ink: #080406;
  --panel: #12080a;
  --panel-raised: #1b0b0f;
  --line: #4a1018;
  --muted: #a88487;
  --paper: #f3e7e8;
  --green: #ed1b2e;
  --green-dim: #8b1020;
  --cyan: #ff727b;
  --grid-line: rgba(237, 27, 46, .035);
  --orb-core: #080406;
  --orb-glow: #ed1b2e;
}
.route-bar, .route-bar a, #route-page { color: var(--green); }
