  --green-dim: #8b1020;
  --cyan: #ff727b;
  --grid-line: rgba(237, 27, 46, .035);
  --orb-core: #080406;
  --orb-glow: #ed1b2e;
}
.route-bar, .route-bar a, #route-page { color: var(--green); }
.route-bar { gap: 4px; }
.page-controls { justify-content: space-between; }
.keyboard-hint { margin-left: 0; }
.theme-picker { position: relative; z-index: 8; flex: 0 0 56px; margin-left: 0; }
.theme-toggle { width: 56px; min-width: 56px; height: 56px; display: grid; place-items: center; padding: 0; border: 0; background: transparent; cursor: pointer; }
.theme-orb { position: relative; width: 30px; height: 30px; border-radius: 50%; background: radial-gradient(circle, var(--orb-core) 0 39%, color-mix(in srgb, var(--orb-glow) 75%, var(--orb-core)) 74%, var(--orb-glow) 100%); box-shadow: 0 0 13px 3px var(--orb-glow), inset 0 0 12px var(--orb-glow); transition: transform .2s ease, box-shadow .2s ease; }
.theme-orb::before { position: absolute; inset: -7px; border: 1px solid var(--green); border-radius: 50%; content: ""; }
.theme-toggle:hover .theme-orb, .theme-toggle[aria-expanded="true"] .theme-orb { transform: scale(1.06); box-shadow: 0 0 18px 4px var(--orb-glow), inset 0 0 12px var(--orb-glow); }
.theme-menu { position: absolute; left: 0; bottom: calc(100% + 8px); width: 240px; display: grid; padding: 5px; border: 1px solid var(--green); background: var(--panel-raised); box-shadow: 0 12px 28px rgba(0, 0, 0, .45); }
.theme-menu[hidden] { display: none; }
.theme-choice { display: grid; grid-template-columns: 20px 1fr 14px; align-items: center; gap: 10px; padding: 11px 9px; border: 0; border-bottom: 1px solid var(--line); background: transparent; color: var(--paper); cursor: pointer; text-align: left; }
.theme-choice:last-child { border-bottom: 0; }
.theme-choice:hover, .theme-choice.is-active { background: rgba(255, 255, 255, .04); }
.theme-choice strong, .theme-choice small { display: block; }
.theme-choice strong { font: 10px var(--mono); }
.theme-choice small { margin-top: 5px; color: var(--muted); font-size: 8px; }
.theme-swatch { width: 15px; height: 15px; border: 1px solid rgba(255, 255, 255, .35); }
.hacker-swatch { background: radial-gradient(circle, #010602 32%, #20ef4f 100%); box-shadow: 0 0 7px #20ef4f; }
.cyberpunk-swatch { background: radial-gradient(circle, #080406 32%, #ed1b2e 100%); box-shadow: 0 0 7px #ed1b2e; }
.theme-check { color: var(--green); font-size: 12px; opacity: 0; }
.theme-choice.is-active .theme-check { opacity: 1; }
.experience-explorer { position: relative; display: grid; grid-template-columns: minmax(185px, .7fr) minmax(0, 1.3fr); gap: 20px; align-items: stretch; }
.experience-folders { position: relative; display: grid; align-content: start; gap: 18px; padding-top: 10px; }
.topic-folder { position: relative; min-height: 88px; display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: 1fr auto; align-items: end; gap: 5px 8px; padding: 12px; border: 1px solid var(--green); border-radius: 5px; background: var(--ink); color: var(--green); cursor: pointer; text-align: left; perspective: 600px; transition: transform .45s cubic-bezier(.2, .8, .2, 1), border-color .18s ease, background-color .18s ease, opacity .3s ease; }
.topic-folder.is-option-selected { z-index: 2; border-color: var(--ink); background: transparent; outline: 0; }
.folder-panel-heading, .folder-entry h4 { text-shadow: 0 0 7px color-mix(in srgb, var(--green) 45%, transparent); }
@keyframes crt-flicker { 0% { opacity: 1; } 12% { opacity: .78; } 13% { opacity: 1; } 47% { opacity: .9; } 48% { opacity: 1; } 71% { opacity: .82; } 72% { opacity: 1; } }
@keyframes crt-roll { 0% { top: -30%; opacity: .35; } 70%, 100% { top: 110%; opacity: .35; } }
.topic-folder .folder-back { position: absolute; z-index: 1; right: 4px; bottom: 4px; left: 4px; height: 88%; border: 1px solid var(--green-dim); border-radius: 0 8px 8px 8px; background: var(--green-dim); }
.topic-folder .folder-back::before { position: absolute; top: -9px; left: -1px; width: 38%; height: 9px; border: 1px solid var(--green-dim); border-bottom: 0; border-radius: 5px 5px 0 0; background: var(--green-dim); content: ""; }
.topic-folder .folder-file { position: absolute; z-index: 2; bottom: 10px; left: 15px; width: calc(100% - 30px); height: 68%; border: 1px solid var(--line); border-radius: 4px; background: var(--paper); box-shadow: 0 2px 5px rgba(0, 0, 0, .14); transition: transform .3s ease-out; }
.topic-folder .folder-file-2 { transform: translate(5px, -5px) rotate(2deg); }
.topic-folder .folder-front { position: absolute; z-index: 4; right: 4px; bottom: 4px; left: 4px; height: 88%; border: 2px solid var(--ink); border-radius: 0 8px 8px 8px; background: var(--green); box-shadow: 0 4px 10px rgba(0, 0, 0, .22); transform-origin: bottom center; backface-visibility: hidden; transition: transform .42s cubic-bezier(.2, .8, .2, 1), background-color .3s ease-out; }
.topic-folder.is-option-selected .folder-front { transform: rotateX(-40deg); background: color-mix(in srgb, var(--green) 78%, var(--ink)); }
.topic-folder.is-open.is-option-selected .folder-front { transform: rotateX(-105deg); }
.topic-folder.is-open:not(.is-option-selected) .folder-front { transform: rotateX(-105deg); }
.topic-folder.is-option-selected .folder-file-1 { transform: translateY(-20px); }
.topic-folder.is-option-selected .folder-file-2 { transform: translateY(-25px) translate(5px, -5px) rotate(4deg); }
.topic-folder > .topic-text, .topic-folder > .folder-count { position: relative; z-index: 5; color: var(--ink); opacity: 1; transition: opacity .3s ease-out; }
.topic-folder > .topic-text { grid-column: 1; grid-row: 2; min-width: 0; }
.topic-folder > .folder-count { grid-column: 2; grid-row: 1; justify-self: end; align-self: start; font-size: 8px; }
.topic-folder.is-option-selected > .topic-text, .topic-folder.is-option-selected > .folder-count { opacity: 0; }
.topic-folder strong { display: block; color: inherit; font: 11px var(--mono); }
.topic-folder small { display: block; margin-top: 5px; color: inherit; font-size: 8px; }
.folder-panel { position: relative; display: flex; flex-direction: column; min-height: 270px; overflow: hidden; border: 1px solid var(--line); border-radius: 4px; background: #080d09; box-shadow: inset 0 0 28px color-mix(in srgb, var(--green) 9%, transparent); }
.folder-items:empty { align-content: center; justify-items: center; }
.folder-items:empty::before { color: var(--muted); font-size: 9px; letter-spacing: .12em; text-align: center; content: "NO SIGNAL // SELECT A DIRECTORY AND PRESS ENTER"; animation: crt-flicker 3.2s steps(1, end) infinite; }
.folder-panel::before, .folder-panel::after { position: absolute; z-index: 2; inset: 0; pointer-events: none; content: ""; }
.folder-panel::before { background: repeating-linear-gradient(to bottom, transparent 0 3px, rgba(0, 0, 0, .3) 3px 4px), radial-gradient(ellipse at center, transparent 55%, rgba(0, 0, 0, .55) 100%); animation: crt-flicker 3.2s steps(1, end) infinite; }
.folder-panel::after { top: -30%; bottom: auto; height: 30px; background: linear-gradient(to bottom, transparent, color-mix(in srgb, var(--green) 24%, transparent), transparent); opacity: 0; }
.experience-explorer.is-opening .folder-panel { animation: crt-power-on .7s steps(14, end) .45s both; }
.experience-explorer.is-opening .folder-items { animation: crt-close-open 1s both; }
.experience-explorer.is-opening .folder-panel::after { animation: crt-sweep .8s ease-out .6s both, crt-roll 6s linear 1.6s infinite; }
.folder-panel-heading, .folder-items { position: relative; z-index: 1; }
.folder-panel-heading { min-height: 39px; display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 0 14px; border-bottom: 1px solid var(--line); color: var(--green); font-size: 9px; }
.folder-panel-heading span:last-child { color: var(--muted); font-size: 7px; }
.folder-items { display: grid; flex: 1; align-content: start; gap: 9px; padding: 13px; }
.folder-entry { position: relative; display: block; min-width: 0; padding: 12px; border-left: 1px solid var(--green-dim); background: var(--panel-raised); color: var(--paper); text-decoration: none; opacity: 0; clip-path: inset(0 100% 0 0); }
.folder-items.is-opening .folder-entry { animation: folder-type-in .9s steps(32, end) calc(.3s + var(--entry-index) * 180ms) forwards; }
@keyframes folder-type-in { 0% { opacity: .45; clip-path: inset(0 100% 0 0); } 100% { opacity: 1; clip-path: inset(0 0 0 0); } }
@keyframes crt-close-open {
  0% { clip-path: inset(0 0 0 0); animation-timing-function: cubic-bezier(.7, 0, 1, .6); }
  35% { clip-path: inset(49.4% 0 49.4% 0); filter: brightness(2.5); animation-timing-function: linear; }
  45% { clip-path: inset(49.4% 0 49.4% 0); animation-timing-function: cubic-bezier(.2, .8, .3, 1); }
  75%, 100% { clip-path: inset(0 0 0 0); }
}
@keyframes crt-power-on {
  0% { filter: brightness(.2) contrast(1.4); }
  8% { filter: brightness(3.5) contrast(1.2); }
  16% { filter: brightness(.35); }
  28% { filter: brightness(2.2); }
  40% { filter: brightness(.6); }
  58% { filter: brightness(1.6); }
  75% { filter: brightness(.9); }
  88% { filter: brightness(1.2); }
  100% { filter: brightness(1); }
}
@keyframes crt-sweep {
  0% { top: 0; opacity: .9; }
  100% { top: 100%; opacity: 0; }
}
.folder-entry h4 { margin: 7px 0 5px; color: var(--paper); font: 500 14px var(--display); }
.folder-entry p { margin: 0; color: #aeb5ad; font-size: 9px; line-height: 1.6; }
.folder-entry .card-meta { margin-top: 8px; }
.folder-entry .card-cta { display: inline-block; margin-top: 8px; color: var(--green); font-size: 8px; }

@media (max-width: 760px) {
  .topbar { min-height: 91px; }
  .route-bar { order: 3; width: 100%; margin: 7px 0 0; font-size: 9px; }
  .home-screen.is-active { grid-template-columns: minmax(0, 1fr); align-content: start; gap: 25px; overflow: hidden; }
  .home-screen .hero-topline { margin-bottom: 20px; }
  .home-screen h1 { font-size: clamp(48px, 11vw, 68px); }
  .home-screen .intro { margin-bottom: 0; }
  .home-directory { width: 100%; }
  .menu-item.folder-tile { min-height: 86px; padding: 9px; }
  .directory-hint { margin-top: 10px; }
  .page-controls { gap: 12px; }
  .keyboard-hint { gap: 4px; font-size: 7px; }
  .keyboard-hint kbd { min-width: 17px; }
  .keyboard-hint .hint-divider { display: none; }
  .experience-explorer { grid-template-columns: 165px minmax(0, 1fr); gap: 12px; }
  .topic-folder { min-height: 70px; padding: 8px; }
  .topic-folder small { font-size: 7px; }
  .folder-panel { min-height: 230px; }
}

@media (max-width: 460px) {
  .route-bar { gap: 6px; font-size: 8px; }
  .home-screen.is-active { gap: 17px; }
  .home-screen .hero-topline { gap: 6px 10px; margin-bottom: 16px; font-size: 6px; }
  .home-screen h1 { font-size: clamp(43px, 11vw, 54px); }
  .menu-item { min-height: 39px; padding: 0 8px; font-size: 9px; }
  .page-controls { gap: 8px; }
  .keyboard-hint { gap: 3px; flex: 1; justify-content: flex-start; font-size: 6px; white-space: nowrap; }
  .keyboard-hint .hint-divider { display: none; }
  .theme-menu { width: min(235px, calc(100vw - 30px)); }
  .experience-explorer { grid-template-columns: 1fr; }
  .experience-folders { position: static; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 5px; }
  .topic-folder { min-height: 62px; padding: 7px 5px; }
  .topic-folder .folder-count { display: none; }
  .topic-folder strong { font-size: 8px; }
  .topic-folder small { overflow: hidden; font-size: 6px; text-overflow: ellipsis; white-space: nowrap; }
  .folder-panel { min-height: 220px; }
}

@media (max-height: 700px) {
  .home-screen.is-active { gap: 12px; padding: 12px 14px; }
  .home-screen .hero-topline { margin-bottom: 8px; }
  .home-screen .eyebrow { margin-bottom: 6px; }
  .home-screen h1 { font-size: clamp(38px, 6vh, 52px); }
  .home-screen .hero-role { margin: 7px 0; }
  .home-screen .intro { margin: 8px 0 0; font-size: 9px; line-height: 1.35; }
  .menu-item.folder-tile { min-height: 60px; grid-template-columns: 23px minmax(0, 1fr) 14px; gap: 3px 6px; padding: 6px; }
  .menu-item.folder-tile .folder-icon { width: 19px; height: 13px; }
  .menu-item.folder-tile .folder-icon::before { top: -4px; width: 7px; height: 3px; }
  .folder-name { font-size: 9px; }
  .folder-meta { font-size: 6px; }
  .directory-heading { min-height: 24px; }
  .directory-hint { margin-top: 3px; font-size: 7px; }
}

@media (max-height: 560px) {
  .page-shell { min-height: 0; }
  .topbar { min-height: 68px; padding-top: 6px; padding-bottom: 3px; }
  .route-bar { order: 0; width: auto; margin: 0 0 0 auto; font-size: 7px; }
  .system-status { font-size: 7px; }
  .page-controls { min-height: 42px; }
  .home-screen.is-active { gap: 8px; }
  .menu-item.folder-tile { min-height: 50px; }
  .directory-heading { min-height: 21px; }
  .directory-hint { margin-top: 1px; }
}

@media (prefers-reduced-motion: reduce) {
  .menu-item.folder-tile .folder-front, .menu-item.folder-tile .folder-file, .topic-folder, .topic-folder .folder-front, .topic-folder .folder-file, .topic-folder > .topic-text, .topic-folder > .folder-count, .folder-panel { transition: none; }
  .experience-explorer.is-opening .folder-panel, .experience-explorer.is-opening .folder-panel::after { animation: none; }
  .folder-items.is-opening .folder-entry { animation-duration: .01ms; animation-delay: 0ms; }
  .folder-panel::before { animation: none; }
}

