.topic-folder { position: relative; min-height: 88px; display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: 1fr auto; align-items: end; gap: 5px 8px; padding: 12px; border: 1px solid var(--green); border-radius: 5px; background: var(--ink); color: var(--green); cursor: pointer; text-align: left; perspective: 600px; transition: transform .45s cubic-bezier(.2, .8, .2, 1), border-color .18s ease, background-color .18s ease, opacity .3s ease; }
