permissionRequest.newFileContents:
const Controller = {
  audioUnlocked: false,

  init() {
    View.init();
    this.bindNavigation();
    this.bindKeyboard();
    this.bindHistory();
    this.bindContactForm();
    this.bindAudioUnlock();
    this.bindThemeMenu();

    const requestedPage = this.screenFromLocation();
    Model.state.screen = requestedPage;
    Model.state.optionIndex = 0;
    View.showScreen(requestedPage);
    if (!window.location.hash) history.replaceState({}, "", `#${Model.basePath}`);
  },

  screenFromLocation() {
    const route = window.location.hash.slice(1);
    if (route === Model.basePath || route === `${Model.basePath}/`) return "home";
    if (route.startsWith(`${Model.basePath}/`)) {
      const screenId = route.slice(Model.basePath.length + 1).split("/")[0];
      return Model.pages.some((page) => page.id === screenId) ? screenId : "home";
    }
    return Model.pages.some((page) => page.id === route) ? route : "home";
  },

  goTo(screenId, addHistory = true) {
    if (!Model.pages.some((page) => page.id === screenId)) return;
    if (screenId === Model.state.screen) return;

    Model.state.screen = screenId;
    Model.state.optionIndex = 0;
    View.showScreen(screenId);
    if (this.audioUnlocked) View.playSelect();
    if (addHistory) {
      const route = screenId === "home" ? Model.basePath : `${Model.basePath}/${screenId}`;
      history.pushState({ screen: screenId }, "", `#${route}`);
    }
  },

  moveOption(direction) {
    const options = View.getOptions();
    if (!options.length) return;
    const none = Model.state.screen === "experience" && !options.some((o) => o.classList.contains("is-option-selected"));
    const base = none ? (direction > 0 ? -1 : 0) : Model.state.optionIndex;
    Model.state.optionIndex = View.setOptionIndex(base + direction);
  },

  bindNavigation() {
    document.addEventListener("click", (event) => {
      const routeControl = event.target.closest("[data-route]");
      const optionControl = event.target.closest("[data-option-step]");

      if (routeControl) {
        event.preventDefault();
        this.goTo(routeControl.dataset.route);
      } else if (optionControl) {
        this.moveOption(Number(optionControl.dataset.optionStep));
      }
    });

    const syncSelection = (event) => {
      const option = event.target.closest?.(View.optionSelector());
      if (option) View.selectOption(option);
    };
    document.addEventListener("focusin", syncSelection);
    document.addEventListener("mouseover", syncSelection);

    View.els.folderButtons.forEach((button, index) => {
      button.addEventListener("mouseleave", () => {
        button.classList.remove("is-option-selected");
        if (document.activeElement === button) button.blur();
      });
      button.addEventListener("click", () => {
        Model.state.optionIndex = index;
        View.setOptionIndex(index, false);
        View.renderExperienceFolder(button.dataset.folder);
      });
    });

    View.els.menuItems.forEach((item, index) => {
      const selectItem = () => {
        Model.state.menuIndex = index;
        Model.state.optionIndex = index;
        View.setMenuSelection(index);
      };
      item.addEventListener("focus", selectItem);
      item.addEventListener("mouseenter", selectItem);
    });
  },

  bindKeyboard() {
    document.addEventListener("keydown", (event) => {
      const isTyping = event.target.matches("input, textarea, select, [contenteditable='true']");
      if (isTyping && event.key !== "Escape") return;

      const themeMenuOpen = !View.els.themeMenu.hidden;
      if (themeMenuOpen && event.key === "Escape") {
        event.preventDefault();
        View.setThemeMenuOpen(false, true);
        return;
      }
      if (themeMenuOpen && ["ArrowUp", "ArrowDown"].includes(event.key)) {
        event.preventDefault();
        const choices = View.els.themeChoices;
        const currentIndex = choices.indexOf(document.activeElement);
        const direction = event.key === "ArrowDown" ? 1 : -1;
        choices[(currentIndex + direction + choices.length) % choices.length].focus();
        return;
      }
      if (themeMenuOpen && ["ArrowLeft", "ArrowRight"].includes(event.key)) {
        event.preventDefault();
        return;
      }

      if (!isTyping && event.key.toLowerCase() === "t") {
        event.preventDefault();
        View.setThemeMenuOpen(true);
      } else if (event.key === "Escape") {
        event.preventDefault();
        this.goTo("home");
      } else if (Model.state.screen === "experience" && event.key === "ArrowRight") {
        event.preventDefault();
        const folder = View.getOptions()[View.optionIndex]?.dataset.folder;
        if (folder && folder !== View.openFolder) View.renderExperienceFolder(folder);
      } else if (["ArrowDown", "ArrowRight"].includes(event.key)) {
        event.preventDefault();
        this.moveOption(1);
      } else if (["ArrowUp", "ArrowLeft"].includes(event.key)) {
        event.preventDefault();
        this.moveOption(-1);
      }
    });
  },

  bindThemeMenu() {
    View.els.themeToggle.addEventListener("click", () => {
      View.setThemeMenuOpen(View.els.themeMenu.hidden);
    });

    View.els.themeChoices.forEach((choice) => {
      choice.addEventListener("click", () => {
        View.setTheme(choice.dataset.themeChoice);
        View.setThemeMenuOpen(false, true);
      });
    });

    document.addEventListener("click", (event) => {
      if (!event.target.closest(".theme-picker")) View.setThemeMenuOpen(false);
    });
  },

  bindHistory() {
    window.addEventListener("popstate", () => {
      Model.state.screen = this.screenFromLocation();
      Model.state.optionIndex = 0;
      View.showScreen(Model.state.screen);
    });
  },

  bindAudioUnlock() {
    const unlock = () => {
      this.audioUnlocked = true;
    };
    window.addEventListener("pointerdown", unlock, { once: true });
    window.addEventListener("keydown", unlock, { once: true });
  },

  bindContactForm() {
    const form = document.querySelector("#contact-form");
    const status = document.querySelector("#form-status");
    const submitButton = form.querySelector("[type='submit']");

    form.addEventListener("submit", async (event) => {
      event.preventDefault();
      const data = Object.fromEntries(new FormData(form).entries());
      if (data._honey) return;

      submitButton.disabled = true;
      status.textContent = "SENDING...";
      try {
        const response = await fetch(`https://formsubmit.co/ajax/${Model.contactEmail}`, {
          method: "POST",
          headers: { "Content-Type": "application/json", Accept: "application/json" },
          body: JSON.stringify({
            name: data.name,
            email: data.email,
            message: data.message,
            _subject: `Portfolio message from ${data.name}`,
          }),
        });
        if (!response.ok) throw new Error("Contact relay unavailable");
        status.textContent = "MESSAGE SENT. THANK YOU.";
        form.reset();
      } catch {
        status.textContent = "OPENING YOUR EMAIL APP...";
        const subject = encodeURIComponent(`Portfolio message from ${data.name}`);
        const body = encodeURIComponent(`${data.message}\n\nReply to: ${data.email}`);
        window.location.href = `mailto:${Model.contactEmail}?subject=${subject}&body=${body}`;
      } finally {
        submitButton.disabled = false;
      }
    });
  },
};

Controller.init();

