        View.setThemeMenuOpen(true);
      } else if (event.key === "Escape") {
        event.preventDefault();
        this.goTo("home");
      } else if (Model.state.screen === "experience" && event.key === "ArrowRight") {
        event.preventDefault();
        const current = View.getOptions()[View.optionIndex];
        const folder = current?.classList.contains("is-option-selected") ? current.dataset.folder : null;
        if (folder && folder !== View.openFolder) View.renderExperienceFolder(folder);
      } else if (["ArrowDown", "ArrowRight"].includes(event.key)) {
        event.preventDefault();
        this.moveOption(1);
