body[data-theme="cyberpunk"] {
  --ink: #080406;
  --panel: #12080a;
  --panel-raised: #1b0b0f;
  --line: #4a1018;
  --muted: #a88487;
  --paper: #f3e7e8;
  --green: #ed1b2e;
  --green-dim: #8b1020;
